SELECT EXISTS (
    SELECT 1 FROM iot_device
    WHERE id = #{deviceId} AND binding_generation = #{bindingGeneration}
)

WITH requested(connection_protocol, identifier_type, identifier_value) AS ( VALUES
(#{connection.definition.protocol.code}, #{connection.definition.identifierType}, #{connection.identifierValue})
) SELECT d.id, d.product_source, d.product_code, d.product_id, d.code, d.serial_number, d.display_name, d.remark, d.thing_model_version, d.binding_generation, d.protocol_code, d.connection_protocol, d.connection_identifier_type, d.connection_identifier_value FROM iot_device d JOIN requested r ON r.connection_protocol = d.connection_protocol AND r.identifier_type = d.connection_identifier_type AND r.identifier_value = d.connection_identifier_value ORDER BY d.id

SELECT device_id, method_code FROM iot_device_access_method WHERE device_id IN
#{deviceId}
ORDER BY device_id, method_code

SELECT EXISTS (
    SELECT 1
    FROM iot_device d
    WHERE d.product_id = #{productId}
      AND (


                  TRUE


                  d.protocol_code NOT IN

                      #{protocolCode}



          OR EXISTS (
              SELECT 1
              FROM iot_device_access_method dam
              WHERE dam.device_id = d.id
                AND


                        TRUE


                        dam.method_code NOT IN

                            #{methodCode}



          )
      )
)

mapper.update:
UPDATE iot_device
SET connection_protocol = #{connectionProtocol},
    connection_identifier_type = #{connectionIdentifierType},
    connection_identifier_value = #{connectionIdentifierValue}
WHERE id = #{deviceId}
